             &lt;/pendingSubscriberPolicy&gt; 
           &lt;/policyEntry&gt; 
           &lt;policyEntry queue= "&gt; "  producerFlowControl= "true" 
            memoryLimit= "1mb" &gt;
            &lt;!--
              Use VM cursor for better latency For more information,
              see: [URL]
            --&gt;
             &lt;pendingQueuePolicy&gt; 
               &lt;vmQueueCursor /&gt; 
